arduino.setup:
pinMode(PIN_R_${COMP_SUFFIX}, OUTPUT);
  pinMode(PIN_G_${COMP_SUFFIX}, OUTPUT);
  pinMode(PIN_B_${COMP_SUFFIX}, OUTPUT);

arduino.loop:
// Red
  analogWrite(PIN_R_${COMP_SUFFIX}, 255);
  analogWrite(PIN_G_${COMP_SUFFIX}, 0);
  analogWrite(PIN_B_${COMP_SUFFIX}, 0);
  delay(500);

  // Green
  analogWrite(PIN_R_${COMP_SUFFIX}, 0);
  analogWrite(PIN_G_${COMP_SUFFIX}, 255);
  analogWrite(PIN_B_${COMP_SUFFIX}, 0);
  delay(500);

  // Blue
  analogWrite(PIN_R_${COMP_SUFFIX}, 0);
  analogWrite(PIN_G_${COMP_SUFFIX}, 0);
  analogWrite(PIN_B_${COMP_SUFFIX}, 255);
  delay(500);

